import csv, hashlib, json, re
from decimal import Decimal, ROUND_HALF_UP
from html.parser import HTMLParser
from pathlib import Path

class VisibleText(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.hidden = 0
        self.parts = []
    def handle_starttag(self, tag, attrs):
        if tag in ('script', 'style'):
            self.hidden += 1
    def handle_endtag(self, tag):
        if tag in ('script', 'style'):
            self.hidden = max(0, self.hidden - 1)
    def handle_data(self, data):
        if not self.hidden and data.strip():
            self.parts.append(data.strip())

root = Path('products/distribution/sqlite-lemonsqueezy-fit')
source = (root / 'raw/fees.html').read_bytes()
parser = VisibleText()
parser.feed(source.decode('utf-8'))
text = ' '.join(' '.join(parser.parts).split())
base = re.search(r'5\s*%\s*\+\s*\$0\.50', text)
report = {'source': 'https://docs.lemonsqueezy.com/help/getting-started/fees', 'source_sha256': hashlib.sha256(source).hexdigest(), 'status': 'base_formula_matched' if base else 'base_formula_unconfirmed', 'source_context': text[max(0, base.start()-150):base.end()+200] if base else None, 'assumptions': ['Illustrative USD price, not an approved listing price', 'Tax-exclusive fee base, no add-ons or refunds in base-only scenario', 'Sensitivity scenarios are hypothetical set-asides, not claims about published surcharges', 'Excludes payout and FX costs, refunds and labor; proceeds are not profit or settlement']}
with (root / 'director-price-sensitivity.csv').open('w', newline='', encoding='utf-8') as handle:
    writer = csv.writer(handle)
    writer.writerow(['illustrative_price_usd','base_fee_usd','base_only_proceeds_usd','hypothetical_extra_set_aside_usd','proceeds_after_set_aside_usd'])
    if base:
        cents = Decimal('0.01')
        for price in map(Decimal, ('9.00','15.00','25.00')):
            fee = (price * Decimal('0.05') + Decimal('0.50')).quantize(cents, rounding=ROUND_HALF_UP)
            for reserve in map(Decimal, ('0.00','0.50','1.00')):
                writer.writerow([price, fee, price-fee, reserve, price-fee-reserve])
(root / 'director-price-sensitivity.json').write_text(json.dumps(report, indent=2) + '\n', encoding='utf-8')
print(json.dumps({'status': report['status'], 'scenarios_written': 9 if base else 0}))
